1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {ListSessionsMessage, OutgoingMessage} from '../../types/messages.js';
6	import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendStreamEnd,
29	  sendSessionList,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  // Per socket, not per session: a socket's off-lock answers leave in the order its frames arrived.
46	  const answers = new WeakMap<WebSocket, Promise<unknown>>();
47	  return function handleMessage(
48	    ws: WebSocket,
49	    session: ChatSession,
50	    rawMessage: unknown,
51	    signal?: AbortSignal
52	  ): Promise<void> {
53	    const validation = validateMessage(rawMessage);
54	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
55	    if (isUserMessageFrame(rawMessage)) {
56	      return lock.run(session.sessionId, () =>
57	        answerInTurn(ws, session, orchestrator, sessionStore, validation, signal)
58	      );
59	    }
60	    // Still beside ping, off the lock: an answer in flight only holds this socket's next off-lock answer.
61	    const ahead = answers.get(ws) ?? Promise.resolve();
62	    const answer = ahead.then(() => wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore)));
63	    // wsErrorHandler settles every outcome itself; the catch only stops a thrown send from stalling this socket's queue.
64	    answers.set(
65	      ws,
66	      answer.catch(() => undefined)
67	    );
68	    return answer;
69	  };
70	}
71	
72	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
73	async function answerInTurn(
74	  ws: WebSocket,
75	  session: ChatSession,
76	  orchestrator: ChatOrchestrator,
77	  sessionStore: SessionStore | undefined,
78	  validation: ValidationResult,
79	  signal: AbortSignal | undefined
80	): Promise<void> {
81	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
82	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
83	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
84	    return;
85	  }
86	  const startedAt = Date.now();
87	  try {
88	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, sessionStore, validation, signal));
89	  } finally {
90	    endTurn(ws, session, signal, startedAt);
91	  }
92	}
93	
94	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
95	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
96	  if (signal?.aborted) {
97	    log.info('message', 'turn abandoned: its socket closed', {
98	      sessionId: session.sessionId,
99	      elapsedMs: Date.now() - startedAt,
100	    });
101	    return;
102	  }
103	  sendStreamEnd(ws);
104	}
105	
106	async function answerUserMessage(
107	  ws: WebSocket,
108	  session: ChatSession,
109	  orchestrator: ChatOrchestrator,
110	  sessionStore: SessionStore | undefined,
111	  validation: ValidationResult,
112	  signal: AbortSignal | undefined
113	): Promise<void> {
114	  const message = validation.valid ? validation.data : undefined;
115	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
116	  await answerFrame(ws, session, validation, sessionStore);
117	}
118	
119	async function answerFrame(
120	  ws: WebSocket,
121	  session: ChatSession,
122	  validation: ValidationResult,
123	  sessionStore: SessionStore | undefined
124	): Promise<void> {
125	  if (!validation.valid) {
126	    log.warn('message', 'validation failed', {error: validation.error});
127	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
128	    return;
129	  }
130	
131	  const message = validation.data;
132	  if (message.type === 'ping') handlePing(ws, message.timestamp);
133	  if (message.type === 'list_sessions') await answerListSessions(ws, session, sessionStore, message);
134	}
135	
136	// Off the lock, beside ping: a history request is not a turn and mutates nothing.
137	async function answerListSessions(
138	  ws: WebSocket,
139	  session: ChatSession,
140	  sessionStore: SessionStore | undefined,
141	  message: ListSessionsMessage
142	): Promise<void> {
143	  let listed: SessionSummary[] | undefined;
144	  try {
145	    // The user is the session's, read here and never from the frame the validator already stripped.
146	    listed = await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before});
147	  } catch (error) {
148	    log.error('ws', 'listing sessions failed', {
149	      sessionId: session.sessionId,
150	      userId: session.userId,
151	      error: messageOf(error),
152	    });
153	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
154	    return;
155	  }
156	  sendSessionList(ws, listed ?? []);
157	}
158	
159	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
160	function isUserMessageFrame(rawMessage: unknown): boolean {
161	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
162	}
163	
164	function messageOf(error: unknown): string {
165	  return error instanceof Error ? error.message : 'Unknown error';
166	}
167	
168	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
169	  try {
170	    await action();
171	  } catch (error) {
172	    const message = messageOf(error);
173	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
174	    log.error('message', 'handling error', {error: message, code});
175	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
176	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
177	      return;
178	    }
179	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
180	  }
181	}
182	
183	async function handleUserMessage(
184	  ws: WebSocket,
185	  session: ChatSession,
186	  orchestrator: ChatOrchestrator,
187	  content: string,
188	  signal: AbortSignal | undefined
189	): Promise<void> {
190	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
191	
192	  const userEntry = createUserEntry(content);
193	  const userIndex = appendEntry(session, userEntry);
194	  sendUpsert(ws, userIndex, userEntry);
195	
196	  const parser = new ThinkingTagParser();
197	  const state: StreamState = {
198	    thinkingIndex: null,
199	    assistantIndex: null,
200	    suppressOutput: false,
201	    sentAssistantIndices: [],
202	  };
203	
204	  let textChunkCount = 0;
205	
206	  try {
207	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
208	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
209	      if (signal?.aborted) break;
210	      textChunkCount = logChunk(chunk, textChunkCount);
211	      processChunk(ws, session, state, parser, chunk);
212	    }
213	  } finally {
214	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
215	    flushHeldText(ws, session, state, parser);
216	    closeCutOff(ws, session, state, 'thinkingIndex');
217	    closeCutOff(ws, session, state, 'assistantIndex');
218	  }
219	
220	  if (textChunkCount > 0) {
221	    log.debug('stream', `received ${textChunkCount} text chunks`);
222	  }
223	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
224	}
225	
226	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
227	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
228	  if (chunk.type === 'text') return textChunkCount + 1;
229	
230	  if (textChunkCount > 0) {
231	    log.debug('stream', `received ${textChunkCount} text chunks`);
232	  }
233	
234	  if (chunk.type === 'tool_result') {
235	    log.debug('stream', 'tool_result chunk', {
236	      messageCount: chunk.clientMessages.length,
237	      types: chunk.clientMessages.map(m => m.type),
238	    });
239	    return 0;
240	  }
241	
242	  log.debug('stream', 'chunk', {type: chunk.type});
243	  return 0;
244	}
245	
246	function processChunk(
247	  ws: WebSocket,
248	  session: ChatSession,
249	  state: StreamState,
250	  parser: ThinkingTagParser,
251	  chunk: MessageChunk
252	): void {
253	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
254	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
255	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
256	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
257	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
258	}
259	
260	function processTextChunk(
261	  ws: WebSocket,
262	  session: ChatSession,
263	  state: StreamState,
264	  parser: ThinkingTagParser,
265	  text: string
266	): void {
267	  const segments = parser.push(text);
268	  for (const segment of segments) {
269	    handleTextSegment(ws, session, state, segment);
270	  }
271	}
272	
273	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
274	  if (segment.type === 'thinking') {
275	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
276	    return;
277	  }
278	  commitAndClear(ws, session, state, 'thinkingIndex');
279	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
280	}
281	
282	function streamSegment(
283	  ws: WebSocket,
284	  session: ChatSession,
285	  state: StreamState,
286	  key: StateIndexKey,
287	  createEntry: EntryFactory,
288	  content: string
289	): void {
290	  const isNew = initSegment(session, state, key, createEntry);
291	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
292	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
293	  appendDelta(session, state[key]!, content);
294	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
295	}
296	
297	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
298	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
299	  markSuppressed(session, index);
300	  sendSkip(ws, index);
301	}
302	
303	function markSuppressed(session: ChatSession, index: number): void {
304	  const entry = session.entries[index];
305	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
306	}
307	
308	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
309	  if (state[key] !== null) return false;
310	  state[key] = appendEntry(session, createEntry());
311	  return true;
312	}
313	
314	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
315	  const index = state[key];
316	  if (index === null) return;
317	
318	  commitEntry(session, index);
319	  state[key] = null;
320	
321	  // Only what the client received can be retracted, and only assistant entries.
322	  if (state.suppressOutput) return;
323	
324	  sendCommit(ws, index);
325	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
326	}
327	
328	function processToolUseChunk(
329	  ws: WebSocket,
330	  session: ChatSession,
331	  toolCall: {name: string; input: Record<string, unknown>}
332	): void {
333	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
334	  const toolIndex = appendEntry(session, toolEntry);
335	  sendUpsert(ws, toolIndex, toolEntry);
336	}
337	
338	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
339	  for (const msg of clientMessages) {
340	    log.debug('stream', 'forwarding client message to frontend', {
341	      type: msg.type,
342	      index: 'index' in msg ? msg.index : undefined,
343	    });
344	    sendJson(ws, msg);
345	  }
346	}
347	
348	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
349	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
350	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
351	  commitOpenEntries(ws, session, state);
352	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
353	
354	  for (const idx of state.sentAssistantIndices) {
355	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
356	    markSuppressed(session, idx);
357	  }
358	
359	  state.sentAssistantIndices = [];
360	  state.suppressOutput = true;
361	}
362	
363	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
364	  flushHeldText(ws, session, state, parser);
365	  commitOpenEntries(ws, session, state);
366	}
367	
368	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
369	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
370	  for (const segment of parser.flush()) {
371	    handleTextSegment(ws, session, state, segment);
372	  }
373	}
374	
375	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
376	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
377	  const index = state[key];
378	  if (index === null) return;
379	  markTruncated(session, index);
380	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
381	  commitAndClear(ws, session, state, key);
382	}
383	
384	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
385	  commitAndClear(ws, session, state, 'thinkingIndex');
386	  commitAndClear(ws, session, state, 'assistantIndex');
387	}
388	
389	function handlePing(ws: WebSocket, timestamp: number): void {
390	  ws.send(JSON.stringify({type: 'pong', timestamp}));
391	}
